def calculate_average(values):
    if not values:
        return 0
    return sum(values) / len(values)

def is_palindrome(text):
    cleaned = text.lower().replace(' ', '')
    return cleaned == cleaned[::-1]

def safe_divide(a, b):
    if b == 0:
        return None
    return a / b

def file_exists(path):
    from pathlib import Path
    return Path(path).exists()
